#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <torch/types.h>

template <int BLOCK_SIZE>
__global__ void compute_rms_kernel(const __half* __restrict__ x,
                                   __half* __restrict__ rms,
                                   const int batch,
                                   const int C,
                                   const int N,
                                   const float eps) {
    // one block per (b, n) pair
    const int b = blockIdx.x;
    const int n = blockIdx.y;

    // stride over feature dimension
    float sum = 0.0f;
    for (int c = threadIdx.x; c < C; c += BLOCK_SIZE) {
        const int idx = ((b * C + c) * N) + n;
        const __half v = x[idx];
        const float fv = __half2float(v);
        sum += fv * fv;
    }

    // reduction in shared memory
    __shared__ float shmem[BLOCK_SIZE];
    shmem[threadIdx.x] = sum;
    __syncthreads();

    // tree reduction
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shmem[threadIdx.x] += shmem[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        const float mean = shmem[0] / static_cast<float>(C);
        const float rms_f = sqrtf(mean + eps);
        rms[b * N + n] = __float2half(rms_f);
    }
}

template <int BLOCK_SIZE>
__global__ void normalize_kernel(const __half* __restrict__ x,
                                 const __half* __restrict__ rms,
                                 __half* __restrict__ y,
                                 const int batch,
                                 const int C,
                                 const int N) {
    const int idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int total = batch * C * N;
    if (idx >= total) return;

    // decode indices
    const int n = idx % N;
    const int tmp = idx / N;
    const int c = tmp % C;
    const int b = tmp / C;

    const __half xv = x[idx];
    const __half rmsv = rms[b * N + n];
    const float out = __half2float(xv) / __half2float(rmsv);
    y[idx] = __float2half(out);
}

// Launcher wrappers (C++ side)
void compute_rms(torch::Tensor x, torch::Tensor rms, const float eps) {
    const int batch = x.size(0);
    const int C = x.size(1);
    const int N = x.numel() / (batch * C);
    const dim3 grid(batch, N);
    const int BLOCK = 256;
    compute_rms_kernel<BLOCK><<<grid, BLOCK>>>(
        reinterpret_cast<__half*>(x.data_ptr()),
        reinterpret_cast<__half*>(rms.data_ptr()),
        batch, C, N, eps);
    cudaGetLastError();
}

void normalize(torch::Tensor x, torch::Tensor rms, torch::Tensor y) {
    const int batch = x.size(0);
    const int C = x.size(1);
    const int N = x.numel() / (batch * C);
    const int total = batch * C * N;
    const int BLOCK = 256;
    const int GRID = (total + BLOCK - 1) / BLOCK;
    normalize_kernel<BLOCK><<<GRID, BLOCK>>>(
        reinterpret_cast<__half*>(x.data_ptr()),
        reinterpret_cast<__half*>(rms.data_ptr()),
        reinterpret_cast<__half*>(y.data_ptr()),
        batch, C, N);
    cudaGetLastError();
}
